def solve(arr, n):
    # Count inversions of type 1: pairs (i, j) where i < j and arr[i] > arr[j]
    # Count inversions of type 2: pairs (i, j) where i < j and arr[i] < arr[j]
    # We need to check if the count of type 1 inversions equals the count of type 2 inversions

    count_type1 = 0  # arr[i] > arr[j]
    count_type2 = 0  # arr[i] < arr[j]

    for i in range(n):
        for j in range(i + 1, n):
            if arr[i] > arr[j]:
                count_type1 += 1
            elif arr[i] < arr[j]:
                count_type2 += 1

    return count_type1 == count_type2
